-- Narrow transport recovery: never rewrites a paid receipt or the completed original image task.
-- At most once, only the first render which is proven rejected at zero cost before any native dispatch claim.
CREATE VIEW tower_theme_zero_dispatch_recovery_scope AS
SELECT e.*,r.id AS rejected_receipt_id,a.sha256 AS manifest_hash,a.renderer_build_hash AS build_hash
FROM tower_autonomy_extensions e
JOIN tower_theme_artifacts a ON a.id=e.artifact_id AND a.extension_id=e.id AND a.repair=0
JOIN tower_autonomy_calls r ON r.cycle_id=e.cycle_id AND r.purpose='lobby-theme-v1:render-0' AND r.model='tool:browser-screenshot' AND r.state='rejected' AND r.actual_micro=0 AND r.reserved_micro=90000
JOIN tower_autonomy_current p ON p.cycle_id=e.cycle_id AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at
JOIN tower_autonomy_cycles c ON c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.budget_micro=e.original_budget_micro
JOIN tower_autonomy_authorizations z ON z.cycle_id=c.id AND z.kind='appearance' AND z.budget_micro=c.budget_micro
JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id AND t.anchor='appearance:halloween:2026'
WHERE e.repair=0 AND e.lease_until IS NULL AND e.audit_json IS NULL AND e.evidence_json IS NULL AND e.review_json IS NOT NULL
AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.original_budget_micro<=(SELECT task_limit_micro FROM tower_autonomy_mandate WHERE id=1)
AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND json_extract(c.evidence_json,'$.generation')=e.generation_id AND e.generation_id=c.id||'-r'||c.repair
AND EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.id=json_extract(c.audit_json,'$.callId') AND q.cycle_id=c.id AND q.state='received' AND q.purpose='independent-task-audit' AND q.model='muse-spark-1.3')
AND EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.id=a.plan_call_id AND q.cycle_id=c.id AND q.state='received' AND q.purpose='lobby-theme-v1:plan' AND q.model='muse-spark-1.3')
AND EXISTS(SELECT 1 FROM tower_autonomy_events m JOIN tower_autonomy_calls q ON q.id=json_extract(m.detail_json,'$.callId') WHERE m.cycle_id=e.cycle_id AND m.kind='lobby-theme-private-memory' AND json_extract(m.detail_json,'$.extensionId')=e.id AND json_extract(m.detail_json,'$.outcome')='blocked' AND q.cycle_id=e.cycle_id AND q.state='received' AND q.purpose='lobby-theme-v1:selfreview')
AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.cycle_id=e.cycle_id AND q.state IN ('unknown','dispatching'))
AND (SELECT count(*) FROM tower_autonomy_calls q WHERE q.cycle_id=e.cycle_id AND q.model='tool:browser-screenshot')=1
AND NOT EXISTS(SELECT 1 FROM tower_autonomy_events d WHERE d.cycle_id=e.cycle_id AND d.kind IN ('lobby-theme-render-dispatched','lobby-theme-rendered','lobby-theme-activated'))
AND NOT EXISTS(SELECT 1 FROM tower_theme_current WHERE extension_id=e.id)
AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE cycle_id=e.cycle_id)+2100000<=e.original_budget_micro
AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE billing_day='2026-10-31')+2100000<=(SELECT daily_limit_micro FROM tower_autonomy_mandate WHERE id=1);

CREATE TRIGGER tower_theme_zero_dispatch_recovery_receipt BEFORE INSERT ON tower_autonomy_events WHEN NEW.kind='lobby-theme-zero-dispatch-recovery' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tower_theme_zero_dispatch_recovery_scope e WHERE e.id=json_extract(NEW.detail_json,'$.extensionId') AND e.state='blocked' AND e.error_code='theme_render_not_dispatched' AND e.outcome='blocked' AND e.step_seq=3 AND NEW.id=e.id||':zero-dispatch-recovery:v1' AND NEW.cycle_id=e.cycle_id AND json_extract(NEW.detail_json,'$.fromSeq')=e.step_seq AND json_extract(NEW.detail_json,'$.receiptId')=e.rejected_receipt_id AND json_extract(NEW.detail_json,'$.artifactId')=e.artifact_id AND json_extract(NEW.detail_json,'$.manifestHash')=e.manifest_hash AND json_extract(NEW.detail_json,'$.rendererBuildHash')=e.build_hash AND json_extract(NEW.detail_json,'$.generation')=e.generation_id AND json_extract(NEW.detail_json,'$.appearanceRevision')=e.appearance_revision AND NEW.created_at>=e.updated_at AND abs((julianday(NEW.created_at)-julianday('now'))*86400000)<=60000 AND NEW.created_at>=e.starts_at AND NEW.created_at<e.ends_at) THEN 1 ELSE RAISE(ABORT,'theme_recovery_denied') END;
END;

DROP TRIGGER tower_theme_extension_binding;
CREATE TRIGGER tower_theme_extension_binding BEFORE UPDATE ON tower_autonomy_extensions WHEN NEW.id!=OLD.id OR NEW.cycle_id!=OLD.cycle_id OR NEW.obligation_version!=OLD.obligation_version OR NEW.capability!=OLD.capability OR NEW.generation_id!=OLD.generation_id OR NEW.appearance_revision!=OLD.appearance_revision OR NEW.original_budget_micro!=OLD.original_budget_micro OR NEW.starts_at!=OLD.starts_at OR NEW.ends_at!=OLD.ends_at OR NEW.created_at!=OLD.created_at OR NEW.repair<OLD.repair OR NEW.repair>OLD.repair+1 OR (NEW.repair!=OLD.repair AND NOT (OLD.state='audit' AND NEW.state='plan' AND json_extract(NEW.audit_json,'$.verdict')='FAIL')) OR OLD.state='complete' OR (OLD.state='blocked' AND NOT (NEW.state='render-0' AND NEW.step_seq=OLD.step_seq+1 AND OLD.step_seq=3 AND OLD.repair=0 AND NEW.repair=OLD.repair AND OLD.error_code='theme_render_not_dispatched' AND NEW.error_code IS NULL AND NEW.outcome='pending' AND NEW.lease_until IS NULL AND NEW.artifact_id IS OLD.artifact_id AND NEW.tool_json IS OLD.tool_json AND NEW.evidence_json IS OLD.evidence_json AND NEW.audit_json IS OLD.audit_json AND NEW.review_json IS OLD.review_json AND EXISTS(SELECT 1 FROM tower_theme_zero_dispatch_recovery_scope e JOIN tower_autonomy_events r ON r.id=e.id||':zero-dispatch-recovery:v1' WHERE e.id=OLD.id AND e.state='blocked' AND r.kind='lobby-theme-zero-dispatch-recovery' AND r.cycle_id=e.cycle_id AND r.created_at=NEW.updated_at AND json_extract(r.detail_json,'$.fromSeq')=OLD.step_seq AND json_extract(r.detail_json,'$.receiptId')=e.rejected_receipt_id AND json_extract(r.detail_json,'$.artifactId')=e.artifact_id AND json_extract(r.detail_json,'$.manifestHash')=e.manifest_hash AND json_extract(r.detail_json,'$.rendererBuildHash')=e.build_hash))) BEGIN SELECT RAISE(ABORT,'theme_binding_immutable'); END;
DROP TRIGGER tower_theme_extension_transition;
CREATE TRIGGER tower_theme_extension_transition BEFORE UPDATE ON tower_autonomy_extensions WHEN NEW.state!=OLD.state AND (NEW.step_seq!=OLD.step_seq+1 OR NEW.lease_until IS NOT NULL OR (NEW.state NOT IN ('selfreview','blocked','complete') AND (OLD.lease_until IS NULL OR OLD.lease_until<=strftime('%Y-%m-%dT%H:%M:%fZ','now') OR NOT EXISTS(SELECT 1 FROM tower_autonomy_extensions e WHERE e.id=OLD.id AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND e.original_budget_micro<=(SELECT task_limit_micro FROM tower_autonomy_mandate WHERE id=1) AND e.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND e.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_autonomy_current p JOIN tower_autonomy_cycles c ON c.id=p.cycle_id JOIN tower_autonomy_authorizations a ON a.cycle_id=c.id JOIN tower_autonomy_task_anchors t ON t.cycle_id=c.id WHERE c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND json_extract(c.evidence_json,'$.generation')=p.generation_id AND p.generation_id=c.id||'-r'||c.repair AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND c.budget_micro=e.original_budget_micro AND a.budget_micro=c.budget_micro AND a.kind='appearance' AND t.anchor='appearance:halloween:2026' AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls x WHERE x.id=json_extract(c.audit_json,'$.callId') AND x.state='received' AND x.cycle_id=c.id AND x.purpose='independent-task-audit' AND x.model='muse-spark-1.3')))))) AND NOT (OLD.state='blocked' AND (NEW.state='render-0' AND NEW.step_seq=OLD.step_seq+1 AND OLD.step_seq=3 AND OLD.repair=0 AND NEW.repair=OLD.repair AND OLD.error_code='theme_render_not_dispatched' AND NEW.error_code IS NULL AND NEW.outcome='pending' AND NEW.lease_until IS NULL AND NEW.artifact_id IS OLD.artifact_id AND NEW.tool_json IS OLD.tool_json AND NEW.evidence_json IS OLD.evidence_json AND NEW.audit_json IS OLD.audit_json AND NEW.review_json IS OLD.review_json AND EXISTS(SELECT 1 FROM tower_theme_zero_dispatch_recovery_scope e JOIN tower_autonomy_events r ON r.id=e.id||':zero-dispatch-recovery:v1' WHERE e.id=OLD.id AND e.state='blocked' AND r.kind='lobby-theme-zero-dispatch-recovery' AND r.cycle_id=e.cycle_id AND r.created_at=NEW.updated_at AND json_extract(r.detail_json,'$.fromSeq')=OLD.step_seq AND json_extract(r.detail_json,'$.receiptId')=e.rejected_receipt_id AND json_extract(r.detail_json,'$.artifactId')=e.artifact_id AND json_extract(r.detail_json,'$.manifestHash')=e.manifest_hash AND json_extract(r.detail_json,'$.rendererBuildHash')=e.build_hash))) BEGIN SELECT RAISE(ABORT,'theme_transition_denied'); END;
